-- JobPulse India — MySQL schema (Hostinger)
-- Ported from supabase/schema.sql + migrations. Postgres → MySQL notes:
--   uuid            → CHAR(36), generated by the app data layer on insert
--   timestamptz     → DATETIME(3) (UTC by convention)
--   text[] / jsonb  → JSON (serialized by the data layer)
--   tsvector        → dropped (no full-text queries in app code)
--   partial unique  → plain unique index (MySQL uniques ignore NULLs)
-- Target: MySQL 8 / MariaDB 10.6+ (Hostinger hPanel), utf8mb4.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS users (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL UNIQUE,
  phone VARCHAR(32),
  role ENUM('candidate','employer','admin') NOT NULL DEFAULT 'candidate',
  password_hash VARCHAR(255),
  email_verified TINYINT(1) NOT NULL DEFAULT 0,
  app_metadata JSON,
  is_banned TINYINT(1) NOT NULL DEFAULT 0,
  current_plan VARCHAR(64) NOT NULL DEFAULT 'free',
  subscription_status ENUM('active','paused','unsubscribed') NOT NULL DEFAULT 'active',
  subscription_started_at DATETIME(3),
  subscription_expires_at DATETIME(3),
  last_seen_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS auth_tokens (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  token_hash VARCHAR(255) NOT NULL,
  type ENUM('reset','verify') NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  used_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY auth_tokens_user_idx (user_id, type),
  CONSTRAINT fk_auth_tokens_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS companies (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(255) NOT NULL UNIQUE,
  slug VARCHAR(255) NOT NULL UNIQUE,
  logo_url VARCHAR(500),
  website VARCHAR(500),
  industry VARCHAR(255),
  city VARCHAR(255),
  state VARCHAR(255),
  country VARCHAR(100) NOT NULL DEFAULT 'India',
  size_range VARCHAR(64),
  description TEXT,
  is_verified TINYINT(1) NOT NULL DEFAULT 0,
  verified TINYINT(1) NOT NULL DEFAULT 0,
  rating DECIMAL(3,2),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS candidate_profiles (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL UNIQUE,
  full_name VARCHAR(255),
  phone VARCHAR(32),
  headline VARCHAR(500),
  bio TEXT,
  education TEXT,
  skills JSON NOT NULL,
  experience TEXT,
  city VARCHAR(255),
  state VARCHAR(255),
  preferred_roles JSON NOT NULL,
  expected_salary INT,
  preferred_job_types JSON NOT NULL,
  language_preference VARCHAR(64) DEFAULT 'English',
  resume_url VARCHAR(500),
  verified TINYINT(1) NOT NULL DEFAULT 0,
  verification_status ENUM('draft','pending','verified','rejected') NOT NULL DEFAULT 'draft',
  verification_requested_at DATETIME(3),
  verified_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_candidate_profiles_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS employer_profiles (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL UNIQUE,
  company_id CHAR(36),
  company_name VARCHAR(255) NOT NULL,
  company_email VARCHAR(255),
  company_email_verified TINYINT(1) NOT NULL DEFAULT 0,
  domain_verification_status VARCHAR(32) NOT NULL DEFAULT 'pending',
  logo_url VARCHAR(500),
  website VARCHAR(500),
  industry VARCHAR(255),
  city VARCHAR(255),
  state VARCHAR(255),
  recruiter_name VARCHAR(255),
  recruiter_phone VARCHAR(32),
  description TEXT,
  verified TINYINT(1) NOT NULL DEFAULT 0,
  approval_status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_employer_profiles_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_employer_profiles_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_sources (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  source_type ENUM('employer','admin','official','partner') NOT NULL,
  transport_type VARCHAR(32) NOT NULL,
  source_url VARCHAR(500) NOT NULL UNIQUE,
  status VARCHAR(16) NOT NULL DEFAULT 'active',
  allow_auto_fetch TINYINT(1) NOT NULL DEFAULT 1,
  config JSON NOT NULL,
  notes TEXT,
  last_fetched_at DATETIME(3),
  last_success_at DATETIME(3),
  last_error TEXT,
  created_by CHAR(36),
  updated_by CHAR(36),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY job_sources_status_idx (status, allow_auto_fetch, updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_fetch_batches (
  id CHAR(36) NOT NULL PRIMARY KEY,
  source_id CHAR(36) NOT NULL,
  started_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  finished_at DATETIME(3),
  status VARCHAR(24) NOT NULL DEFAULT 'running',
  total_found INT NOT NULL DEFAULT 0,
  total_new INT NOT NULL DEFAULT 0,
  total_duplicates INT NOT NULL DEFAULT 0,
  total_failed INT NOT NULL DEFAULT 0,
  total_published INT NOT NULL DEFAULT 0,
  error_message TEXT,
  KEY job_fetch_batches_source_idx (source_id, started_at),
  CONSTRAINT fk_job_fetch_batches_source FOREIGN KEY (source_id) REFERENCES job_sources(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS raw_fetched_jobs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  source_id CHAR(36) NOT NULL,
  raw_title TEXT,
  raw_company TEXT,
  raw_location TEXT,
  raw_description MEDIUMTEXT,
  raw_apply_url VARCHAR(1000),
  raw_salary VARCHAR(255),
  raw_experience VARCHAR(255),
  raw_job_type VARCHAR(64),
  raw_posted_date VARCHAR(64),
  raw_deadline VARCHAR(64),
  raw_data_json JSON NOT NULL,
  content_hash VARCHAR(128) NOT NULL,
  fetch_batch_id CHAR(36),
  status VARCHAR(16) NOT NULL DEFAULT 'new',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY raw_fetched_jobs_hash_idx (content_hash),
  CONSTRAINT fk_raw_fetched_jobs_source FOREIGN KEY (source_id) REFERENCES job_sources(id) ON DELETE CASCADE,
  CONSTRAINT fk_raw_fetched_jobs_batch FOREIGN KEY (fetch_batch_id) REFERENCES job_fetch_batches(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS normalized_jobs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  raw_job_id CHAR(36) NOT NULL UNIQUE,
  title VARCHAR(500) NOT NULL,
  slug VARCHAR(255) NOT NULL DEFAULT '',
  company_name VARCHAR(255) NOT NULL,
  description MEDIUMTEXT NOT NULL,
  responsibilities JSON NOT NULL,
  requirements JSON NOT NULL,
  skills JSON NOT NULL,
  salary_min INT,
  salary_max INT,
  salary_type ENUM('monthly','yearly','stipend'),
  city VARCHAR(255),
  state VARCHAR(255),
  country VARCHAR(100) NOT NULL DEFAULT 'India',
  job_type ENUM('full-time','part-time','contract','freelance','internship','walk-in'),
  work_mode ENUM('remote','hybrid','onsite'),
  experience_min INT,
  experience_max INT,
  education_required TEXT,
  industry VARCHAR(255),
  openings INT NOT NULL DEFAULT 1,
  deadline DATE,
  apply_url VARCHAR(1000),
  source_url VARCHAR(1000),
  source_type VARCHAR(32) NOT NULL,
  quality_score DECIMAL(5,2),
  duplicate_score DECIMAL(5,2),
  status VARCHAR(24) NOT NULL DEFAULT 'pending_review',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_normalized_jobs_raw FOREIGN KEY (raw_job_id) REFERENCES raw_fetched_jobs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS jobs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  company_id CHAR(36),
  employer_id CHAR(36),
  normalized_job_id CHAR(36),
  category_slug VARCHAR(128),
  title VARCHAR(500) NOT NULL,
  slug VARCHAR(255) NOT NULL UNIQUE,
  company_name VARCHAR(255) NOT NULL,
  description MEDIUMTEXT NOT NULL,
  responsibilities JSON NOT NULL,
  requirements JSON NOT NULL,
  skills JSON NOT NULL,
  salary_min INT,
  salary_max INT,
  salary_type ENUM('monthly','yearly','stipend') NOT NULL DEFAULT 'yearly',
  city VARCHAR(255),
  state VARCHAR(255),
  country VARCHAR(100) NOT NULL DEFAULT 'India',
  location VARCHAR(500),
  job_type ENUM('full-time','part-time','contract','freelance','internship','walk-in'),
  work_mode ENUM('remote','hybrid','onsite'),
  education_required TEXT,
  experience_required TEXT,
  experience_min INT,
  experience_max INT,
  industry VARCHAR(255),
  openings INT NOT NULL DEFAULT 1,
  recruiter_contact VARCHAR(255),
  status ENUM('draft','pending','active','expired','rejected') NOT NULL DEFAULT 'draft',
  approval_status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  no_candidate_payment TINYINT(1) NOT NULL DEFAULT 1,
  salary_disclosed TINYINT(1) NOT NULL DEFAULT 1,
  government_source_verified TINYINT(1) NOT NULL DEFAULT 0,
  suspicious_flags JSON NOT NULL,
  is_suspicious TINYINT(1) NOT NULL DEFAULT 0,
  moderation_notes TEXT,
  is_verified TINYINT(1) NOT NULL DEFAULT 0,
  is_featured TINYINT(1) NOT NULL DEFAULT 0,
  apply_url VARCHAR(1000),
  application_url VARCHAR(1000),
  deadline DATE,
  source_type ENUM('employer','admin','official','partner'),
  source_url VARCHAR(1000),
  expires_at DATETIME(3),
  published_at DATETIME(3),
  approved_at DATETIME(3),
  approved_by CHAR(36),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY jobs_normalized_job_id_idx (normalized_job_id),
  KEY jobs_status_approval_idx (status, approval_status, updated_at),
  KEY jobs_category_idx (category_slug, status),
  CONSTRAINT fk_jobs_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL,
  CONSTRAINT fk_jobs_employer FOREIGN KEY (employer_id) REFERENCES employer_profiles(id) ON DELETE SET NULL,
  CONSTRAINT fk_jobs_normalized FOREIGN KEY (normalized_job_id) REFERENCES normalized_jobs(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_fetch_runs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  source_id CHAR(36) NOT NULL,
  status VARCHAR(16) NOT NULL DEFAULT 'running',
  trigger_type VARCHAR(16) NOT NULL DEFAULT 'manual',
  started_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  completed_at DATETIME(3),
  fetched_count INT NOT NULL DEFAULT 0,
  parsed_count INT NOT NULL DEFAULT 0,
  pending_review_count INT NOT NULL DEFAULT 0,
  duplicate_count INT NOT NULL DEFAULT 0,
  error_message TEXT,
  meta JSON NOT NULL,
  KEY job_fetch_runs_source_idx (source_id, started_at),
  CONSTRAINT fk_job_fetch_runs_source FOREIGN KEY (source_id) REFERENCES job_sources(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_ingestion_items (
  id CHAR(36) NOT NULL PRIMARY KEY,
  source_id CHAR(36) NOT NULL,
  fetch_run_id CHAR(36),
  source_job_key VARCHAR(255),
  source_type ENUM('employer','admin','official','partner') NOT NULL,
  source_url VARCHAR(1000) NOT NULL,
  application_url VARCHAR(1000),
  title VARCHAR(500) NOT NULL,
  company_name VARCHAR(255) NOT NULL,
  city VARCHAR(255),
  state VARCHAR(255),
  country VARCHAR(100) NOT NULL DEFAULT 'India',
  description MEDIUMTEXT NOT NULL,
  responsibilities JSON NOT NULL,
  requirements JSON NOT NULL,
  skills JSON NOT NULL,
  job_type ENUM('full-time','part-time','contract','freelance','internship','walk-in'),
  work_mode ENUM('remote','hybrid','onsite'),
  salary_type ENUM('monthly','yearly','stipend'),
  salary_min INT,
  salary_max INT,
  education_required TEXT,
  experience_required TEXT,
  experience_min INT,
  experience_max INT,
  industry VARCHAR(255),
  openings INT,
  deadline DATE,
  recruiter_contact VARCHAR(255),
  company_website VARCHAR(500),
  raw_payload JSON NOT NULL,
  normalized_payload JSON NOT NULL,
  enrichment_payload JSON NOT NULL,
  dedupe_fingerprint VARCHAR(255) NOT NULL,
  dedupe_status VARCHAR(36) NOT NULL DEFAULT 'new',
  duplicate_of_job_id CHAR(36),
  duplicate_of_ingestion_item_id CHAR(36),
  review_status VARCHAR(24) NOT NULL DEFAULT 'pending_review',
  review_notes TEXT,
  approved_by CHAR(36),
  approved_at DATETIME(3),
  rejected_by CHAR(36),
  rejected_at DATETIME(3),
  published_job_id CHAR(36),
  published_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY job_ingestion_items_source_job_key_idx (source_id, source_job_key),
  KEY job_ingestion_items_review_idx (review_status, created_at),
  KEY job_ingestion_items_dedupe_idx (dedupe_fingerprint),
  CONSTRAINT fk_ingestion_items_source FOREIGN KEY (source_id) REFERENCES job_sources(id) ON DELETE CASCADE,
  CONSTRAINT fk_ingestion_items_run FOREIGN KEY (fetch_run_id) REFERENCES job_fetch_runs(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS applications (
  id CHAR(36) NOT NULL PRIMARY KEY,
  job_id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  candidate_id CHAR(36) NOT NULL,
  resume_id CHAR(36),
  resume_url VARCHAR(500),
  resume_storage_path VARCHAR(500),
  cover_letter TEXT,
  status ENUM('applied','viewed','shortlisted','interview','rejected','offered') NOT NULL DEFAULT 'applied',
  employer_notes TEXT,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY applications_job_candidate_uq (job_id, candidate_id),
  UNIQUE KEY applications_job_user_uq (job_id, user_id),
  CONSTRAINT fk_applications_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE,
  CONSTRAINT fk_applications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_applications_candidate FOREIGN KEY (candidate_id) REFERENCES candidate_profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS saved_jobs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  job_id CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY saved_jobs_user_job_uq (user_id, job_id),
  CONSTRAINT fk_saved_jobs_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_saved_jobs_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_match_scores (
  id CHAR(36) NOT NULL PRIMARY KEY,
  candidate_id CHAR(36) NOT NULL,
  job_id CHAR(36) NOT NULL,
  match_score INT NOT NULL,
  matching_skills JSON NOT NULL,
  missing_skills JSON NOT NULL,
  recommendation TEXT NOT NULL,
  reason TEXT NOT NULL,
  candidate_updated_at DATETIME(3),
  job_updated_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY job_match_scores_uq (candidate_id, job_id),
  CONSTRAINT fk_match_candidate FOREIGN KEY (candidate_id) REFERENCES candidate_profiles(id) ON DELETE CASCADE,
  CONSTRAINT fk_match_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS resumes (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  title VARCHAR(255) NOT NULL,
  content_json JSON NOT NULL,
  file_url VARCHAR(500),
  storage_path VARCHAR(500),
  template_key VARCHAR(64),
  version INT NOT NULL DEFAULT 1,
  ats_score INT,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_resumes_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE applications
  ADD CONSTRAINT fk_applications_resume FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE SET NULL;

-- Replaces the object-storage bucket used previously. Resume uploads are
-- capped at 5 MB by the API, so MEDIUMBLOB (16 MB) is ample.
CREATE TABLE IF NOT EXISTS resume_files (
  id CHAR(36) NOT NULL PRIMARY KEY,
  storage_path VARCHAR(500) NOT NULL UNIQUE,
  user_id CHAR(36) NOT NULL,
  file_name VARCHAR(255) NOT NULL,
  content_type VARCHAR(128) NOT NULL,
  byte_size INT NOT NULL,
  content MEDIUMBLOB NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY resume_files_user_idx (user_id),
  CONSTRAINT fk_resume_files_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS resume_analyses (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  resume_id CHAR(36),
  score INT,
  job_description_text MEDIUMTEXT,
  match_score INT,
  missing_keywords JSON NOT NULL,
  suggestions JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_resume_analyses_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_resume_analyses_resume FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS interview_sessions (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  role VARCHAR(255) NOT NULL,
  mode VARCHAR(64) NOT NULL,
  questions_json JSON NOT NULL,
  answers_json JSON NOT NULL,
  score INT,
  report_json JSON NOT NULL,
  feedback TEXT,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_interview_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS whatsapp_subscriptions (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36),
  phone_number VARCHAR(32) NOT NULL UNIQUE,
  city VARCHAR(255),
  category_slug VARCHAR(128),
  is_opted_in TINYINT(1) NOT NULL DEFAULT 1,
  status ENUM('active','paused','unsubscribed') NOT NULL DEFAULT 'active',
  metadata JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_whatsapp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS government_jobs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  category_slug VARCHAR(128),
  title VARCHAR(500) NOT NULL,
  slug VARCHAR(255) NOT NULL UNIQUE,
  department VARCHAR(255) NOT NULL,
  category VARCHAR(255) NOT NULL,
  state VARCHAR(255),
  eligibility TEXT,
  age_limit VARCHAR(255),
  fees VARCHAR(255),
  last_date DATE,
  official_url VARCHAR(1000),
  notification_url VARCHAR(1000),
  summary TEXT,
  official_last_checked_at DATETIME(3),
  source_id CHAR(36),
  source_url VARCHAR(1000),
  official_apply_url VARCHAR(1000),
  application_fee VARCHAR(255),
  status VARCHAR(24) NOT NULL DEFAULT 'approved',
  fetch_key VARCHAR(255),
  review_notes TEXT,
  approved_by CHAR(36),
  approved_at DATETIME(3),
  rejected_by CHAR(36),
  rejected_at DATETIME(3),
  metadata JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY government_jobs_fetch_key_idx (fetch_key),
  KEY government_jobs_status_idx (status, updated_at),
  CONSTRAINT fk_government_jobs_source FOREIGN KEY (source_id) REFERENCES job_sources(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS jobpulse_import_jobs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  fetch_key VARCHAR(255),
  slug VARCHAR(255) NOT NULL UNIQUE,
  title VARCHAR(500) NOT NULL,
  department VARCHAR(255),
  category VARCHAR(255),
  category_slug VARCHAR(128),
  state VARCHAR(255),
  eligibility TEXT,
  age_limit VARCHAR(255),
  fees VARCHAR(255),
  application_fee VARCHAR(255),
  last_date DATE,
  official_url VARCHAR(1000),
  notification_url VARCHAR(1000),
  official_apply_url VARCHAR(1000),
  source_url VARCHAR(1000),
  summary TEXT,
  status VARCHAR(24) NOT NULL DEFAULT 'approved',
  openings VARCHAR(64),
  salary VARCHAR(255),
  syllabus TEXT,
  selection_process TEXT,
  important_dates JSON,
  faq JSON,
  metadata JSON,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY jobpulse_import_jobs_fetch_key_idx (fetch_key),
  KEY jobpulse_import_jobs_status_idx (status, updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS internships (
  id CHAR(36) NOT NULL PRIMARY KEY,
  category_slug VARCHAR(128),
  company_id CHAR(36),
  title VARCHAR(500) NOT NULL,
  slug VARCHAR(255) NOT NULL UNIQUE,
  company VARCHAR(255) NOT NULL,
  stipend VARCHAR(255),
  duration VARCHAR(255),
  location VARCHAR(500),
  work_mode ENUM('remote','hybrid','onsite'),
  is_paid TINYINT(1) NOT NULL DEFAULT 0,
  skills JSON NOT NULL,
  apply_url VARCHAR(1000),
  deadline DATE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_internships_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS blog_posts (
  id CHAR(36) NOT NULL PRIMARY KEY,
  title VARCHAR(500) NOT NULL,
  slug VARCHAR(255) NOT NULL UNIQUE,
  excerpt TEXT,
  content MEDIUMTEXT NOT NULL,
  cover_image VARCHAR(500),
  meta_title VARCHAR(255),
  meta_description VARCHAR(500),
  keywords JSON NOT NULL,
  schema_type VARCHAR(64) DEFAULT 'Article',
  status ENUM('draft','pending','active','expired','rejected') NOT NULL DEFAULT 'draft',
  published_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS seo_pages (
  id CHAR(36) NOT NULL PRIMARY KEY,
  page_type VARCHAR(64) NOT NULL,
  slug VARCHAR(255) NOT NULL UNIQUE,
  title VARCHAR(500) NOT NULL,
  meta_title VARCHAR(255),
  meta_description VARCHAR(500),
  content MEDIUMTEXT,
  faq_json JSON NOT NULL,
  city VARCHAR(255),
  state VARCHAR(255),
  category VARCHAR(255),
  indexable TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS payments (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36),
  amount INT NOT NULL,
  plan VARCHAR(64) NOT NULL,
  subscription_type VARCHAR(64),
  razorpay_order_id VARCHAR(255) UNIQUE,
  razorpay_payment_id VARCHAR(255),
  razorpay_signature VARCHAR(255),
  notes JSON NOT NULL,
  status ENUM('created','paid','failed','refunded','cancelled') NOT NULL DEFAULT 'created',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_payments_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS notifications (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36),
  title VARCHAR(500) NOT NULL,
  message TEXT NOT NULL,
  type ENUM('system','job_alert','application','payment','admin') NOT NULL DEFAULT 'system',
  channel ENUM('in_app','email','whatsapp') NOT NULL DEFAULT 'in_app',
  is_read TINYINT(1) NOT NULL DEFAULT 0,
  metadata JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS analytics_events (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36),
  candidate_id CHAR(36),
  employer_id CHAR(36),
  job_id CHAR(36),
  payment_id CHAR(36),
  session_id VARCHAR(255),
  event_name VARCHAR(255) NOT NULL,
  event_data JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY analytics_job_event_idx (job_id, event_name, created_at),
  KEY analytics_employer_event_idx (employer_id, event_name, created_at),
  KEY analytics_candidate_event_idx (candidate_id, event_name, created_at),
  CONSTRAINT fk_analytics_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_analytics_candidate FOREIGN KEY (candidate_id) REFERENCES candidate_profiles(id) ON DELETE SET NULL,
  CONSTRAINT fk_analytics_employer FOREIGN KEY (employer_id) REFERENCES employer_profiles(id) ON DELETE SET NULL,
  CONSTRAINT fk_analytics_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE SET NULL,
  CONSTRAINT fk_analytics_payment FOREIGN KEY (payment_id) REFERENCES payments(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_reports (
  id CHAR(36) NOT NULL PRIMARY KEY,
  job_id CHAR(36) NOT NULL,
  user_id CHAR(36),
  reported_by CHAR(36),
  reason TEXT NOT NULL,
  details TEXT,
  reviewed_by CHAR(36),
  resolution_notes TEXT,
  status ENUM('open','reviewing','resolved','dismissed') NOT NULL DEFAULT 'open',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_job_reports_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE,
  CONSTRAINT fk_job_reports_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS admin_logs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  admin_user_id CHAR(36),
  action VARCHAR(255) NOT NULL,
  entity_type VARCHAR(64) NOT NULL,
  entity_id CHAR(36),
  metadata JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_admin_logs_user FOREIGN KEY (admin_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS company_reviews (
  id CHAR(36) NOT NULL PRIMARY KEY,
  company_id CHAR(36) NOT NULL,
  user_id CHAR(36),
  rating INT NOT NULL,
  title VARCHAR(255),
  review TEXT,
  pros TEXT,
  cons TEXT,
  status ENUM('pending','published','rejected') NOT NULL DEFAULT 'pending',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_company_reviews_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  CONSTRAINT fk_company_reviews_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS salary_data (
  id CHAR(36) NOT NULL PRIMARY KEY,
  company_id CHAR(36),
  job_title VARCHAR(500) NOT NULL,
  city VARCHAR(255),
  state VARCHAR(255),
  experience_range VARCHAR(64),
  salary_min INT,
  salary_max INT,
  salary_type ENUM('monthly','yearly','stipend') NOT NULL DEFAULT 'yearly',
  source VARCHAR(255),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_salary_data_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_categories (
  id CHAR(36) NOT NULL PRIMARY KEY,
  slug VARCHAR(128) NOT NULL UNIQUE,
  name VARCHAR(255) NOT NULL,
  job_family ENUM('private','government','internship') NOT NULL,
  description TEXT,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY job_categories_family_idx (job_family, sort_order, name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS skills (
  id CHAR(36) NOT NULL PRIMARY KEY,
  slug VARCHAR(255) NOT NULL UNIQUE,
  name VARCHAR(255) NOT NULL UNIQUE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS job_skill_links (
  id CHAR(36) NOT NULL PRIMARY KEY,
  job_id CHAR(36) NOT NULL,
  skill_id CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY job_skill_links_uq (job_id, skill_id),
  CONSTRAINT fk_job_skill_links_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE,
  CONSTRAINT fk_job_skill_links_skill FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
